import{_ as o,o as a,c as i,ag as n}from"./chunks/framework.CvgP6Fyv.js";const c=JSON.parse('{"title":"Python 简介","description":"","frontmatter":{},"headers":[],"relativePath":"docs/python/basics/01-python-introduction.md","filePath":"docs/python/basics/01-python-introduction.md"}'),l={name:"docs/python/basics/01-python-introduction.md"};function e(h,t,s,r,p,d){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="python-简介" tabindex="-1">Python 简介 <a class="header-anchor" href="#python-简介" aria-label="Permalink to &quot;Python 简介&quot;">​</a></h1><h2 id="什么是-python" tabindex="-1">什么是 Python？ <a class="header-anchor" href="#什么是-python" aria-label="Permalink to &quot;什么是 Python？&quot;">​</a></h2><p>Python 是一种高级、解释型、通用的编程语言。它由 Guido van Rossum 于 1991 年创建，以其简洁的语法和强大的功能而闻名。</p><h2 id="python-的特点" tabindex="-1">Python 的特点 <a class="header-anchor" href="#python-的特点" aria-label="Permalink to &quot;Python 的特点&quot;">​</a></h2><ul><li><strong>简单易学</strong>：语法清晰，代码可读性强</li><li><strong>跨平台</strong>：支持 Windows、Linux、macOS 等操作系统</li><li><strong>丰富的标准库</strong>：内置大量实用的模块和函数</li><li><strong>强大的社区支持</strong>：拥有庞大的开发者社区和丰富的第三方库</li><li><strong>多范式支持</strong>：支持面向对象、命令式、函数式编程</li></ul><h2 id="python-的应用领域" tabindex="-1">Python 的应用领域 <a class="header-anchor" href="#python-的应用领域" aria-label="Permalink to &quot;Python 的应用领域&quot;">​</a></h2><ul><li>Web 开发</li><li>数据分析与科学计算</li><li>人工智能与机器学习</li><li>自动化运维</li><li>游戏开发</li><li>网络爬虫</li><li>桌面应用开发</li></ul><h2 id="python-的版本" tabindex="-1">Python 的版本 <a class="header-anchor" href="#python-的版本" aria-label="Permalink to &quot;Python 的版本&quot;">​</a></h2><p>目前 Python 主要有两个版本：</p><ul><li>Python 2.x（已停止维护）</li><li>Python 3.x（当前主流版本）</li></ul><p>建议使用 Python 3.x 版本进行开发。</p><h2 id="安装-python" tabindex="-1">安装 Python <a class="header-anchor" href="#安装-python" aria-label="Permalink to &quot;安装 Python&quot;">​</a></h2><ol><li>访问 Python 官网：<a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">https://www.python.org/downloads/</a></li><li>下载对应操作系统的安装包</li><li>运行安装程序，确保勾选&quot;Add Python to PATH&quot;</li><li>验证安装：打开命令行，输入 <code>python --version</code></li></ol><h2 id="第一个-python-程序" tabindex="-1">第一个 Python 程序 <a class="header-anchor" href="#第一个-python-程序" aria-label="Permalink to &quot;第一个 Python 程序&quot;">​</a></h2><p>让我们编写一个简单的 Python 程序：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, World!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>将上述代码保存为 <code>hello.py</code>，然后在命令行中运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.py</span></span></code></pre></div><h2 id="python-开发环境" tabindex="-1">Python 开发环境 <a class="header-anchor" href="#python-开发环境" aria-label="Permalink to &quot;Python 开发环境&quot;">​</a></h2><p>推荐使用以下工具进行 Python 开发：</p><ul><li><p><strong>IDE</strong>：</p><ul><li>PyCharm</li><li>VS Code</li><li>Jupyter Notebook</li></ul></li><li><p><strong>包管理工具</strong>：</p><ul><li>pip</li><li>conda</li></ul></li><li><p><strong>虚拟环境</strong>：</p><ul><li>venv</li><li>virtualenv</li></ul></li></ul><h2 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/" target="_blank" rel="noreferrer">Python 官方文档</a></li><li><a href="https://docs.python.org/zh-cn/3/tutorial/index.html" target="_blank" rel="noreferrer">Python 教程</a></li><li><a href="https://www.liaoxuefeng.com/wiki/1016959663602400" target="_blank" rel="noreferrer">Python 入门教程 - 廖雪峰</a></li></ul>',23)])])}const u=o(l,[["render",e]]);export{c as __pageData,u as default};
